			if err != nil {
				return nil, err
			}

			buildInfo := core.ExtractBuildInfo(ctx)
			client, err := scw.NewClient(
				scw.WithJWT(tt.Token),
				scw.WithUserAgent(buildInfo.GetUserAgent()),
			)
			if err != nil {
				return nil, err
			}

			api := iam.NewAPI(client)
			req := &iam.CreateAPIKeyRequest{
				UserID:      &tt.Jwt.AudienceID,
				Description: "Generated by the Scaleway CLI",
			}

			if args.ProjectID != "" {
				req.DefaultProjectID = &args.ProjectID
			}

			if args.ExpiresAt != nil {
				req.ExpiresAt = args.ExpiresAt
			}
			apiKey, err := api.CreateAPIKey(req)
			if err != nil {
				return nil, err
			}

			// Get the project to retrieve the organization ID
			accountAPI := account.NewProjectAPI(client)
			project, err := accountAPI.GetProject(&account.ProjectAPIGetProjectRequest{
				ProjectID: apiKey.DefaultProjectID,
			})
			if err != nil {
				return nil, err
			}

			resp, err := initCommand.Command().Run(ctx, &initCommand.Args{
				AccessKey:      apiKey.AccessKey,
				SecretKey:      *apiKey.SecretKey,
				ProjectID:      apiKey.DefaultProjectID,
				OrganizationID: project.OrganizationID,
				Region:         scw.RegionFrPar,
				Zone:           scw.ZoneFrPar1,
			})
			if err != nil {
				// Cleanup API Key if init failed
				logger.Warningf("Init failed, cleaning API key.\n")
				cleanErr := api.DeleteAPIKey(&iam.DeleteAPIKeyRequest{
					AccessKey: apiKey.AccessKey,
				})
				if cleanErr != nil {
					logger.Warningf("Failed to clean API key: %s\n", err.Error())
				}

				return nil, err
			}

			return resp, nil
		},
